import {loadArt,drawViews,drawItem,drawCosmetic,drawHair,exportLook,lips,hairs} from './art.js';
const $=s=>document.querySelector(s),clone=o=>structuredClone(o);
const initial={outfit:0,lip:4,blush:35,liner:2,hair:0,shoes:0,accessory:0,hairstyle:0,earrings:-1,bracelet:-1,pose:0,expression:0};
let jewelryCategory='accessories',styleFilter='all';
let state=clone(initial),history=[],category='clothes',challenge=0,looks=[],ready=false,toastTimer;
const outfits=[['Leather jacket','Rebel at heart'],['Lace blouse','Soft strength'],['Rose cardigan','A warmer you'],['Plaid skirt','Classic chaos'],['Wide-leg jeans','Everyday mood'],['Slip dress','For later'],['Pink ribbon dress','Sweet as a daydream'],['Floral skirt','Garden romance'],['Lavender cardigan','Soft little moments']];
const shoes=[['Black leather','The original'],['Cherry leather','A darker romance'],['Ivory leather','A softer edge']];
const accessories=[['Silver chains','A little starlight'],['Velvet choker','Heart on a string'],['Pearl necklace','Quietly classic'],['Ruby heart','A little romance'],['Gold layers','Golden hour'],['Safety pin','Punk keepsake']];
const hairstyles=['Tousled bob','Long waves','High ponytail','Twin braids'];
const earrings=[['Silver hoops','Everyday shine'],['Star drops','After-dark sparkle'],['Pearl drops','Quiet romance']];
const bracelets=[['Silver bracelet','A little charm'],['Leather cuff','A tougher edge'],['Pearl bracelet','Softly classic']];
const challenges=[{name:'Backstage romance',brief:'Punk layers, berry lips and silver jewelry. Dress for the encore.',checks:[['Choose the leather jacket or plaid skirt',s=>[0,3].includes(s.outfit)],['Wear berry lipstick',s=>s.lip===4],['Add silver chains or a velvet choker',s=>[0,1].includes(s.accessory)],['Finish with winged eyeliner',s=>s.liner===2]]},{name:'Sunday café',brief:'Soft textures, a natural lip and a little warmth. A slow morning in the city.',checks:[['Choose a soft or romantic outfit',s=>[1,2,6,7,8].includes(s.outfit)],['Wear nude or rose lipstick',s=>s.lip<2],['Keep eyeliner bare or soft',s=>s.liner<2],['Add a little blush (20–60%)',s=>s.blush>=20&&s.blush<=60]]},{name:'Midnight muse',brief:'An evening silhouette, a bold lip and something that catches the light.',checks:[['Choose the slip dress',s=>s.outfit===5],['Wear brick or berry lipstick',s=>s.lip>=3],['Add silver chains or pearls',s=>[0,2].includes(s.accessory)],['Finish with black boots',s=>s.shoes===0]]}];
function valid(s){return s&&['outfit','lip','blush','liner','hair','shoes','accessory'].every(k=>Number.isInteger(s[k]))&&s.outfit>=0&&s.outfit<9&&s.lip>=0&&s.lip<5&&s.blush>=0&&s.blush<=100&&s.liner>=0&&s.liner<3&&s.hair>=0&&s.hair<4&&s.shoes>=0&&s.shoes<3&&s.accessory>=-1&&s.accessory<6&&(s.hairstyle===undefined||(Number.isInteger(s.hairstyle)&&s.hairstyle>=0&&s.hairstyle<4))&&(s.pose===undefined||(Number.isInteger(s.pose)&&s.pose>=0&&s.pose<3))&&(s.expression===undefined||(Number.isInteger(s.expression)&&s.expression>=0&&s.expression<4))&&['earrings','bracelet'].every(k=>s[k]===undefined||(Number.isInteger(s[k])&&s[k]>=-1&&s[k]<3));}
const migrate=s=>({...initial,...s});
try{const data=JSON.parse(localStorage.getItem('after-school-v1')||'null');if(valid(data?.state))state=migrate(data.state);if(Array.isArray(data?.looks))looks=data.looks.filter(l=>valid(l.state)&&typeof l.name==='string').slice(0,12).map(l=>({...l,state:migrate(l.state)}));if(Number.isInteger(data?.challenge)&&data.challenge>=0&&data.challenge<3)challenge=data.challenge;}catch{}
function persist(){try{localStorage.setItem('after-school-v1',JSON.stringify({state,looks,challenge}));return true;}catch{toast('Browser storage is unavailable. You can still download your look.');return false;}}
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3000);}
function change(patch){history.push(clone(state));if(history.length>60)history.shift();Object.assign(state,patch);render();persist();}
function swatches(){$('#hairstyle-options').replaceChildren(...hairstyles.map((name,i)=>{const b=document.createElement('button');b.className='hairstyle';b.setAttribute('aria-label',name);b.setAttribute('aria-pressed',state.hairstyle===i);const art=document.createElement('canvas');drawHair(art,state,i);art.setAttribute('aria-hidden','true');b.append(art,document.createTextNode(name));b.onclick=()=>change({hairstyle:i});return b;}));const lipNames=['Nude','Rose','Mauve','Brick','Berry'];$('#lip-swatches').replaceChildren(...lips.map((color,i)=>{const b=document.createElement('button');b.className='swatch';b.style.setProperty('--swatch',color);b.title=lipNames[i];b.setAttribute('aria-label',`${lipNames[i]} lipstick`);b.setAttribute('aria-pressed',state.lip===i);const art=document.createElement('canvas');drawCosmetic(art,state,'lip',i);art.setAttribute('aria-hidden','true');b.append(art);b.onclick=()=>change({lip:i});return b;}));$('#hair-swatches').replaceChildren(...hairs.map((color,i)=>{const b=document.createElement('button');b.className='swatch';b.style.setProperty('--swatch',color);b.setAttribute('aria-label',['Ink black hair','Chestnut hair','Cherry hair','Honey hair'][i]);b.setAttribute('aria-pressed',state.hair===i);b.title=b.getAttribute('aria-label');b.innerHTML='<span class="hair"></span>';b.onclick=()=>change({hair:i});return b;}));$('#liner-options').replaceChildren(...['Bare','Soft','Winged'].map((name,i)=>{const b=document.createElement('button');b.className='liner';b.setAttribute('aria-pressed',state.liner===i);b.setAttribute('aria-label',`${name} eyeliner`);const art=document.createElement('canvas');drawCosmetic(art,state,'liner',i);art.setAttribute('aria-hidden','true');b.append(art,document.createTextNode(name));b.onclick=()=>change({liner:i});return b;}));}
function inventory(){
const jewelry=category==='accessories';
$('#jewelry-tabs').hidden=!jewelry;$('#style-filters').hidden=category!=='clothes';
const kind=jewelry?jewelryCategory:category;
const entries=kind==='clothes'?outfits:kind==='shoes'?shoes:kind==='earrings'?[...earrings,['No earrings','Keep it simple']]:kind==='bracelets'?[...bracelets,['No bracelet','Keep it simple']]:[...accessories,['No necklace','Let the outfit speak']];
const key=kind==='clothes'?'outfit':kind==='shoes'?'shoes':kind==='earrings'?'earrings':kind==='bracelets'?'bracelet':'accessory';
$('#inventory').replaceChildren(...entries.map(([title,subtitle],i)=>{const index=jewelry&&i===entries.length-1?-1:i;if(kind==='clothes'&&((styleFilter==='punk'&&!([0,3,4,5].includes(index)))||(styleFilter==='romantic'&&!([1,2,6,7,8].includes(index)))))return null;const b=document.createElement('button');b.className='item'+(state[key]===index?' selected':'');b.setAttribute('aria-pressed',state[key]===index);b.setAttribute('aria-label',title);const canvas=document.createElement('canvas');canvas.setAttribute('aria-hidden','true');drawItem(canvas,kind,index,state);const strong=document.createElement('strong');strong.textContent=title;const small=document.createElement('small');small.textContent=subtitle;b.append(canvas,strong,small);b.onclick=()=>change({[key]:index});return b;}).filter(Boolean));
$('#inventory-note').textContent=category==='clothes'?'Choose a complete outfit, then make it yours.':category==='shoes'?(state.outfit>=6?'Romantic outfits include matching Mary Janes or ballet flats. Boot finishes apply to punk outfits.':'Your platform boots, in three finishes.'):'Mix a necklace, earrings and a bracelet.';
}

function render(){if(!ready)return;drawViews(state);document.querySelectorAll('[data-pose]').forEach(b=>b.setAttribute('aria-pressed',Number(b.dataset.pose)===state.pose));document.querySelectorAll('[data-expression]').forEach(b=>b.setAttribute('aria-pressed',Number(b.dataset.expression)===state.expression));swatches();inventory();$('#blush').value=state.blush;$('#blush-value').value=state.blush+'%';$('#undo').disabled=history.length===0;$('#saved-count').textContent=looks.length?`(${looks.length})`:'';$('#challenge-title').textContent=challenges[challenge].name;}
function open(content){$('#modal-body').replaceChildren();if(typeof content==='string')$('#modal-body').innerHTML=content;else $('#modal-body').append(content);if(!$('#modal').open)$('#modal').showModal();}
function showChallenges(){open('<h2 class="dialog-title">A look for every story.</h2><p class="dialog-intro">Choose a brief, dress your character, then check your look. Each match earns one star. Free styling is always welcome.</p><div class="challenge-list"></div>');challenges.forEach((ch,i)=>{const b=document.createElement('button');b.className='challenge-card'+(i===challenge?' selected':'');b.innerHTML=`<h3>${ch.name}</h3><p>${ch.brief}</p><span>${i===challenge?'Current brief':'Style this story →'}</span>`;b.onclick=()=>{challenge=i;$('#challenge-progress').textContent='Make it your own.';persist();render();$('#modal').close();toast('New brief: '+ch.name);};$('.challenge-list').append(b);});}
function checkLook(){const ch=challenges[challenge],score=ch.checks.filter(([,fn])=>fn(state)).length;$('#challenge-progress').textContent=`${score} / 4 style stars`;open(`<h2 class="dialog-title">${ch.name}</h2><div class="score">${'★'.repeat(score)}${'☆'.repeat(4-score)}</div><p class="dialog-intro">${score===4?'You nailed the brief. Save this one.':'Your look, your rules. These details bring it closer to the brief.'}</p><ul class="score-details">${ch.checks.map(([label,fn])=>`<li>${fn(state)?'✓':'○'} ${label}</li>`).join('')}</ul><button class="dialog-button" id="back-style">Keep styling</button>`);$('#back-style').onclick=()=>$('#modal').close();}
function saveDialog(){if(looks.length>=12){toast('Your album has 12 looks. Remove one to make room.');showSaved();return;}open('<h2 class="dialog-title">Keep this feeling.</h2><p class="dialog-intro">Save this look to your browser album. Download a portrait to keep a copy anywhere.</p><img class="save-preview" alt="Preview of your current look"><form id="save-form"><label class="name-field">Look name<input id="look-name" maxlength="40" required autocomplete="off"></label><button class="dialog-button" type="submit">Add to my album</button></form>');$('.save-preview').src=exportLook(state).toDataURL('image/jpeg',.8);$('#look-name').value=challenges[challenge].name;$('#save-form').onsubmit=e=>{e.preventDefault();const name=$('#look-name').value.trim();if(!name){$('#look-name').focus();return;}looks.unshift({id:crypto.randomUUID(),name,state:clone(state)});const ok=persist();render();$('#modal').close();toast(ok?'Look saved to your album.':'Saved for this visit. Download it to keep a copy.');};}
function download(s){const a=document.createElement('a');a.download='after-school-look.png';a.href=exportLook(s).toDataURL('image/png');a.click();}
function showSaved(){open('<h2 class="dialog-title">Your little lookbook.</h2><p class="dialog-intro">Saved on this browser. Restore a look to keep styling, or download it as a portrait.</p><div class="saved-grid"></div>');if(!looks.length){$('.saved-grid').innerHTML='<p class="empty">Your next favorite look belongs here.</p>';return;}looks.forEach(l=>{const card=document.createElement('article');card.className='saved-card';const img=document.createElement('img');img.src=exportLook(l.state).toDataURL('image/jpeg',.65);img.alt=l.name;const h=document.createElement('h3');h.textContent=l.name;const actions=document.createElement('div');actions.className='saved-actions';for(const [label,fn]of [['Wear',()=>{change(clone(l.state));$('#modal').close();toast('Look restored.');}],['Download',()=>download(l.state)],['Remove',()=>{looks=looks.filter(x=>x.id!==l.id);persist();render();showSaved();}]]){const b=document.createElement('button');b.textContent=label;b.setAttribute('aria-label',label+' '+l.name);b.onclick=fn;actions.append(b);}card.append(img,h,actions);$('.saved-grid').append(card);});}
$('#close-modal').onclick=()=>$('#modal').close();$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close();}});
$('#challenges').onclick=showChallenges;$('#challenge-title').onclick=showChallenges;$('#check-look').onclick=checkLook;$('#saved').onclick=showSaved;$('#studio').onclick=()=>{$('#modal').close();window.scrollTo({top:0,behavior:'smooth'});};$('#help').onclick=()=>open('<h2 class="dialog-title">Your studio. Your rules.</h2><ol class="help-copy"><li>Pick one of nine complete outfits from the wardrobe.</li><li>Try lipstick, blush and eyeliner in the vanity. Switch to Hair for hairstyles and color.</li><li>Mix necklaces, earrings and bracelets. Punk outfits offer boot finishes; romantic outfits have matching shoes.</li><li>Choose a pose and facial expression for the finished portrait.</li><li>Follow a challenge brief and check your look for up to four stars—or style freely.</li><li>Save your favorites, then open Saved looks to wear or download them.</li></ol><p class="dialog-intro">No account needed to play. Your album stays in this browser. Clearing browser storage removes saved looks.</p>');
for(const tab of ['makeup','hair'])$('#'+tab+'-tab').onclick=()=>{for(const t of ['makeup','hair']){$('#'+t+'-tab').setAttribute('aria-selected',t===tab);$('#'+t+'-panel').hidden=t!==tab;}};
$('#wardrobe-tabs').addEventListener('click',e=>{const b=e.target.closest('[data-category]');if(!b)return;category=b.dataset.category;$('#wardrobe-tabs').querySelectorAll('button').forEach(t=>t.setAttribute('aria-selected',t===b));inventory();});
$('#jewelry-tabs').addEventListener('click',e=>{const b=e.target.closest('[data-jewelry]');if(!b)return;jewelryCategory=b.dataset.jewelry;$('#jewelry-tabs').querySelectorAll('button').forEach(t=>t.setAttribute('aria-pressed',t===b));inventory();});
let blushBefore=null;$('#blush').addEventListener('input',()=>{if(!blushBefore)blushBefore=clone(state);state.blush=Number($('#blush').value);drawViews(state);$('#blush-value').value=state.blush+'%';});$('#blush').addEventListener('change',()=>{if(blushBefore){history.push(blushBefore);blushBefore=null;}render();persist();});$('#undo').onclick=()=>{if(history.length){state=history.pop();render();persist();}};$('#random').onclick=()=>change({outfit:Math.floor(Math.random()*9),lip:Math.floor(Math.random()*5),blush:Math.floor(Math.random()*71),liner:Math.floor(Math.random()*3),hair:Math.floor(Math.random()*4),shoes:Math.floor(Math.random()*3),accessory:Math.floor(Math.random()*7)-1,hairstyle:Math.floor(Math.random()*4),earrings:Math.floor(Math.random()*4)-1,bracelet:Math.floor(Math.random()*4)-1,pose:Math.floor(Math.random()*3),expression:Math.floor(Math.random()*4)});$('#save').onclick=saveDialog;
window.render_game_to_text=()=>JSON.stringify({ready,mode:'styling',state,category,challenge:challenges[challenge].name,stars:challenges[challenge].checks.filter(([,fn])=>fn(state)).length,savedLooks:looks.length,undo:history.length});window.advanceTime=()=>render();
loadArt().then(()=>{ready=true;$('#loading').hidden=true;render();}).catch(error=>{$('#loading').textContent='The artwork could not load. Please refresh to try again.';console.error(error);});

$('#pose-controls').addEventListener('click',e=>{const b=e.target.closest('[data-pose]');if(b)change({pose:Number(b.dataset.pose)});});
$('#expression-controls').addEventListener('click',e=>{const b=e.target.closest('[data-expression]');if(b)change({expression:Number(b.dataset.expression)});});
$('#style-filters').addEventListener('click',e=>{const b=e.target.closest('[data-style]');if(!b)return;styleFilter=b.dataset.style;$('#style-filters').querySelectorAll('button').forEach(t=>t.setAttribute('aria-pressed',t===b));inventory();});
